const body = $input.first().json.body || $input.first().json;
const candidateId = body.candidate_id || body.id;

if (!candidateId) {
  throw new Error("Thiếu candidate_id hợp lệ!");
}

return [{
  json: {
    candidate_id: Number(candidateId),
    requested_by: body.requested_by || "HR_System"
  }
}];

const candidate = $input.first().json;
const pos = (candidate.applied_position || "").toLowerCase();

let interviewer = { name: "Nguyễn HR", email: "hr@company.com", role: "HR Manager" };
if (pos.includes("frontend")) {
  interviewer = { name: "Trần Văn Tech", email: "lead.frontend@company.com", role: "Frontend Lead" };
} else if (pos.includes("backend") || pos.includes("nodejs")) {
  interviewer = { name: "Lê Hoàng Dev", email: "lead.backend@company.com", role: "Backend Lead" };
} else if (pos.includes("ai") || pos.includes("data")) {
  interviewer = { name: "Phạm Trí Tuệ", email: "lead.ai@company.com", role: "AI Lead" };
}

const now = new Date();
now.setDate(now.getDate() + 2);
const dateStr = now.toISOString().split("T")[0];

const proposedSlots = [
  `${dateStr} 09:30:00`,
  `${dateStr} 14:30:00`
];

return [{
  json: {
    candidate_id: candidate.id,
    full_name: candidate.full_name,
    email: candidate.email,
    position: candidate.applied_position,
    interviewer,
    proposedSlots
  }
}];

const item = $input.first().json;

const prompt = `Bạn là trợ lý điều phối tuyển dụng ATS.
Ứng viên: ${item.full_name}
Vị trí: ${item.position}
Người phỏng vấn: ${item.interviewer.name} (${item.interviewer.role})
Các khung giờ khả dụng:
1. ${item.proposedSlots[0]}
2. ${item.proposedSlots[1]}

Hãy chọn 1 khung giờ phù hợp nhất và tạo mã link Google Meet ngẫu nhiên dạng https://meet.google.com/dfj-amei-jzt.
BẮT BUỘC chỉ trả về đúng định dạng JSON thuần túy (không markdown, không giải thích):
{
  "selected_time": "YYYY-MM-DD HH:mm:ss",
  "meeting_link": "https://meet.google.com/dfj-amei-jzt",
  "schedule_note": "Ghi chú ngắn gọn cho ứng viên và HR chuẩn bị"
}`;

return [{
  json: {
    ...item,
    prompt
  }
}];

const prev = $('Step 6: Build AI Prompt').first().json;
const item = $input.first().json;
let parsed = null;

try {
  let text = item.candidates?.[0]?.content?.parts?.[0]?.text || '';
  text = text.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(text);
} catch (e) {
  parsed = null;
}

if (!parsed || !parsed.selected_time) {
  parsed = {
    selected_time: prev.proposedSlots[0],
    meeting_link: 'https://meet.google.com/dfj-amei-jzt',
    schedule_note: 'Lịch phỏng vấn xếp tự động theo slot khả dụng mặc định.'
  };
}

return [{
  json: {
    candidate_id: prev.candidate_id,
    full_name: prev.full_name,
    email: prev.email,
    position: prev.position,
    interviewer_name: prev.interviewer.name,
    interviewer_email: prev.interviewer.email,
    interview_time: parsed.selected_time,
    meeting_link: parsed.meeting_link,
    schedule_note: parsed.schedule_note
  }
}];

